sparql_tries.sparql:
SELECT DISTINCT ?year WHERE {
  ?camp rc:campaignNumber "26V430000" ;
        rc:affects ?v .
  ?v rc:modelYear ?year ;
     rc:ofModel ?m .
  ?m rc:name "TELLURIDE" ;
     rc:ofMake ?mk .
  ?mk rc:name "KIA" .
}
ORDER BY ?year

SELECT DISTINCT ?componentName WHERE {
  ?camp rc:campaignNumber "10V388000" ;
        rc:affectsComponent ?comp .
  ?comp rc:name ?componentName .
}
ORDER BY ?componentName

SELECT ?reportDate WHERE {
  ?c rc:campaignNumber "23V651000" ;
     rc:reportReceivedDate ?reportDate .
}

SELECT ?potentiallyAffected WHERE {
  ?campaign rc:campaignNumber "26V430000" ;
            rc:potentiallyAffected ?potentiallyAffected .
}

SELECT DISTINCT ?campaignNumber ?makeName WHERE {
  ?c a rc:RecallCampaign ;
     rc:doNotDrive true ;
     rc:campaignNumber ?campaignNumber ;
     rc:affects ?variant .
  ?variant rc:ofModel ?model .
  ?model rc:ofMake ?make .
  ?make rc:name ?makeName .
  FILTER(?makeName IN ("HYUNDAI", "KIA", "GENESIS"))
}
ORDER BY ?makeName ?campaignNumber

SELECT ?campaignNumber ?initiatedBy WHERE {
  ?recall a rc:RecallCampaign ;
          rc:campaignNumber ?campaignNumber ;
          rc:initiatedBy ?initiatedBy .
  FILTER(
    CONTAINS(UCASE(STR(?initiatedBy)), "OVSC") ||
    CONTAINS(UCASE(STR(?initiatedBy)), "VEHICLE SAFETY COMPLIANCE")
  )
}
ORDER BY ?campaignNumber

SELECT DISTINCT ?campaignNumber WHERE {
  ?c a rc:RecallCampaign ;
     rc:campaignNumber ?campaignNumber ;
     rc:reportReceivedDate ?received ;
     rc:affects ?variant .
  ?variant rc:ofModel ?model .
  ?model rc:name "PALISADE" ;
         rc:ofMake ?make .
  ?make rc:name "HYUNDAI" .
  FILTER (YEAR(?received) = 2024)
}
ORDER BY ?campaignNumber

SELECT DISTINCT ?makeName ?modelName WHERE {
  ?comp rc:name "SERVICE BRAKES, HYDRAULIC:ANTILOCK/TRACTION CONTROL/ELECTRONIC LIMITED SLIP:CONTROL UNIT/MODULE" .
  ?camp rc:affectsComponent ?comp ;
        rc:affects ?variant .
  ?variant rc:ofModel ?model .
  ?model rc:name ?modelName ;
         rc:ofMake ?make .
  ?make rc:name ?makeName .
}
ORDER BY ?makeName ?modelName

SELECT ?campaignNo (COUNT(DISTINCT ?makeName) AS ?brandCount) (GROUP_CONCAT(DISTINCT ?makeName; separator=", ") AS ?brands)
WHERE {
  ?c a rc:RecallCampaign ;
     rc:campaignNumber ?campaignNo ;
     rc:affects ?v .
  ?v rc:ofModel ?m .
  ?m rc:ofMake ?mk .
  ?mk rc:name ?makeName .
  FILTER(?makeName IN ("HYUNDAI", "KIA", "GENESIS"))
}
GROUP BY ?campaignNo
HAVING (COUNT(DISTINCT ?makeName) > 1)
ORDER BY DESC(?brandCount) ?campaignNo

SELECT DISTINCT ?campaignNumber WHERE {
  ?campaign rc:affects ?variant ;
            rc:campaignNumber ?campaignNumber .
  ?variant rc:modelYear ?modelYear ;
           rc:ofModel ?model .
  FILTER(STRSTARTS(STR(?modelYear), "2021"))
  ?model rc:name "SANTA FE" ;
         rc:ofMake ?make .
  ?make rc:name "HYUNDAI" .
}
ORDER BY ?campaignNumber

SELECT DISTINCT ?genesisModel
WHERE {
  ?kiaCamp rc:affects ?kiaVariant ;
           rc:affectsComponent ?comp .
  ?kiaVariant rc:ofModel ?kiaModel .
  ?kiaModel rc:name "TELLURIDE" ;
            rc:ofMake ?kiaMake .
  ?kiaMake rc:name "KIA" .

  ?genesisCamp rc:affectsComponent ?comp ;
               rc:affects ?genesisVariant .
  ?genesisVariant rc:ofModel ?gModel .
  ?gModel rc:ofMake ?genesisMake ;
          rc:name ?genesisModel .
  ?genesisMake rc:name "GENESIS" .
}
ORDER BY ?genesisModel

SELECT ?modelName (COUNT(DISTINCT ?c) AS ?campaigns)
WHERE {
  ?c a rc:RecallCampaign ;
     rc:affects ?v .
  ?v rc:ofModel ?m .
  ?m rc:name ?modelName .
}
GROUP BY ?modelName
ORDER BY DESC(?campaigns) ?modelName

SELECT (COUNT(DISTINCT ?c) AS ?campaignCount) WHERE {
  ?c a rc:RecallCampaign ;
     rc:reportReceivedDate ?d ;
     rc:affects ?v .
  ?v rc:ofModel ?m .
  ?m rc:ofMake ?mk .
  ?mk rc:name ?makeName .
  FILTER(?makeName IN ("HYUNDAI", "KIA", "GENESIS"))
  FILTER(YEAR(?d) = 2023)
}

SELECT ?topName (COUNT(DISTINCT ?model) AS ?modelCount) WHERE {
  ?camp a rc:RecallCampaign ;
        rc:affectsComponent ?comp ;
        rc:affects ?variant .
  ?variant rc:ofModel ?model .
  ?comp skos:broader* ?top .
  FILTER NOT EXISTS { ?top skos:broader ?parent }
  ?top rc:name ?topName .
}
GROUP BY ?topName
ORDER BY DESC(?modelCount) ?topName

SELECT ?campaignNumber ?potentiallyAffected WHERE {
  ?c a rc:RecallCampaign ;
     rc:parkOutside true ;
     rc:campaignNumber ?campaignNumber ;
     rc:potentiallyAffected ?potentiallyAffected .
}
ORDER BY DESC(?potentiallyAffected)
LIMIT 1

SELECT (COUNT(DISTINCT ?campaign) AS ?odiCampaignCount)
WHERE {
  ?campaign a rc:RecallCampaign ;
            rc:initiatedBy ?initiator .
  FILTER(
    REGEX(STR(?initiator), "ODI", "i") ||
    REGEX(STR(?initiator), "Office of Defects Investigation", "i") ||
    REGEX(STR(?initiator), "Defects Investigation", "i")
  )
}

SELECT ?top_name (COUNT(DISTINCT ?c) AS ?campaigns)
WHERE {
  ?make a rc:Make ;
        rc:name "GENESIS" .
  ?model rc:ofMake ?make .
  ?variant rc:ofModel ?model .
  ?c a rc:RecallCampaign ;
     rc:affects ?variant ;
     rc:affectsComponent ?comp .
  ?comp skos:broader* ?top .
  FILTER NOT EXISTS { ?top skos:broader ?up }
  ?top rc:name ?top_name .
}
GROUP BY ?top_name
ORDER BY DESC(?campaigns) ?top_name

SELECT (COUNT(DISTINCT ?year) AS ?yearCount) WHERE {
  ?make rc:name "HYUNDAI" .
  ?model rc:ofMake ?make ;
         rc:name "SONATA" .
  ?variant rc:ofModel ?model ;
           rc:modelYear ?year .
  ?campaign rc:affects ?variant .
}

SELECT ?year (COUNT(DISTINCT ?c) AS ?n) WHERE {
  ?c a rc:RecallCampaign ;
     rc:reportReceivedDate ?d ;
     rc:affects ?v .
  ?v rc:ofModel ?m .
  ?m rc:ofMake ?make .
  ?make rc:name ?mn .
  FILTER(UCASE(STR(?mn)) IN ("HYUNDAI", "KIA", "GENESIS"))
  BIND(YEAR(?d) AS ?year)
}
GROUP BY ?year
ORDER BY DESC(?n) ?year
LIMIT 1

SELECT DISTINCT ?campaignNumber WHERE {
  ?rc a rc:RecallCampaign ;
      rc:campaignNumber ?campaignNumber .
  OPTIONAL { ?rc rc:defectSummary ?d }
  OPTIONAL { ?rc rc:rootCause ?r }
  OPTIONAL { ?rc rc:consequenceSummary ?c }
  BIND(CONCAT(COALESCE(?d, ""), " ", COALESCE(?r, ""), " ", COALESCE(?c, "")) AS ?text)
  FILTER(REGEX(?text, "hydrogen", "i") && REGEX(?text, "leak|detect", "i"))
}
ORDER BY ?campaignNumber

SELECT DISTINCT ?campaignNumber WHERE {
  ?campaign a rc:RecallCampaign ;
            rc:campaignNumber ?campaignNumber ;
            rc:affectsComponent ?comp .
  ?comp rc:name ?compName .
  FILTER(CONTAINS(UCASE(STR(?compName)), "CHARG") || CONTAINS(UCASE(STR(?compName)), "ICCU"))
}
ORDER BY ?campaignNumber

SELECT DISTINCT ?campaignNo WHERE {
  ?rc a rc:RecallCampaign ;
      rc:campaignNumber ?campaignNo ;
      rc:defectSummary ?defect .
  OPTIONAL { ?rc rc:rootCause ?rootCause }
  OPTIONAL { ?rc rc:affectsComponent ?comp . ?comp rc:name ?compName }
  BIND(CONCAT(?defect, " ", COALESCE(?rootCause, ""), " ", COALESCE(?compName, "")) AS ?text)
  FILTER(REGEX(?text, "(water|moisture)", "i") && REGEX(?text, "(tow|trailer|hitch)", "i"))
}
ORDER BY ?campaignNo

SELECT DISTINCT ?campaignNumber WHERE {
  ?c a rc:RecallCampaign ;
     rc:campaignNumber ?campaignNumber .
  {
    ?c rc:affectsComponent ?comp .
    ?comp rc:name ?compName .
    FILTER(REGEX(?compName, "CONNECTING ROD|ROD BEARING", "i"))
  }
  UNION
  {
    ?c rc:defectSummary ?defect .
    FILTER(REGEX(?defect, "connecting rod", "i") && REGEX(?defect, "bearing", "i"))
  }
}
ORDER BY ?campaignNumber
